using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using Unity.Profiling;
namespace SporeGobbo.Geometry.Preview
{
 [DefaultExecutionOrder(1500)]public sealed class Stage54Benchmark:MonoBehaviour
 {
  Stage54Preview env;Stage47Preview live;Stage49Preview cam;string output;bool finished;ProfilerRecorder allocation,main;readonly Results result=new Results();
  [Serializable]public class Results{public string error="",colorSpace;public double explorationSeconds;public int initialKnown,finalKnown,laps;public List<string> checks=new List<string>();public List<Frame> frames=new List<Frame>();public List<Metric> metrics=new List<Metric>();public List<Resource> resources=new List<Resource>();public List<Shot> shots=new List<Shot>();public List<long> probes=new List<long>();}
  [Serializable]public class Frame{public string phase;public double interval,host,discovery,publication,structure,emergence,main;public long allocation;public int resident,known,shown,uploads,built,evicted;public bool ready;}
  [Serializable]public class Metric{public string name;public double ms;public int count;}
  [Serializable]public class Resource{public string name;public long managed,unity;public int meshes,buffers,materials,resident,pool;}
  [Serializable]public class Shot{public string name;public double above,below,normalScale;public int anchor,known,shown,resident,visible;public float x,y;}
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-stage54Output");if(at<0)yield break;output=args[at+1];Directory.CreateDirectory(output);env=GetComponent<Stage54Preview>();env.Initialize();env.automation=true;live=env.Live;live.automation=true;cam=env.CameraStudy;env.showPanel=false;env.Lab.paused=true;QualitySettings.vSyncCount=0;Application.runInBackground=true;bool controlsOnly=Array.IndexOf(args,"-stage54ControlsOnly")>=0;Application.targetFrameRate=controlsOnly?-1:60;allocation=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread");result.colorSpace=QualitySettings.activeColorSpace.ToString();result.initialKnown=env.State.Discovery.Remembered.Count;yield return Settle();RecordMetric("initialization",env.InitializationMs);RecordMetric("organic-assembly",env.AssemblyMs);ResourceSample("initial");for(int p=0;p<4;p++){var b=new byte[1048576];b[0]=1;yield return null;result.probes.Add(allocation.Valid?allocation.LastValue:-1);GC.KeepAlive(b);}yield return Capture("01-start-only-chamber-known");
   // Real five minutes at60FPS; logical motion uses measured dt and the existing swept movement. No bookmarks during the circuit.
   double start=Time.realtimeSinceStartupAsDouble,previous=start;int waypoint=1;var path=new List<Point2>();int cursor=0;bool routeReady=false;double nextSample=60;while(controlsOnly?result.laps<1:Time.realtimeSinceStartupAsDouble-start<300){double now=Time.realtimeSinceStartupAsDouble,dt=controlsOnly?1.0/60:Math.Min(.05,now-previous);previous=now;if(!routeReady){var nav=new LabNavigation(live.World,new Point2(live.Position.x,live.Position.y));path.Clear();Check(nav.TraceToRoot(env.State.Fixture.Tour[waypoint],1,path),"Circuit route "+waypoint+" lap "+result.laps);path.Reverse();cursor=0;routeReady=true;}
    if(live.Ready){while(cursor<path.Count&&Vector2.Distance(live.Position,Stage54Preview.V(path[cursor]))<.00001f)cursor++;if(cursor>=path.Count){waypoint++;if(waypoint>=env.State.Fixture.Tour.Count){waypoint=0;result.laps++;}routeReady=false;}else{var delta=Stage54Preview.V(path[cursor])-live.Position;live.Step(Vector2.ClampMagnitude(delta/(float)(10*Math.Max(.001,dt)),1),delta,false,(float)dt);}}env.Process(dt);yield return null;Record(controlsOnly?"physical-circuit-replay":"five-minute-exploration",(Time.realtimeSinceStartupAsDouble-now)*1000);if(Time.realtimeSinceStartupAsDouble-start>=nextSample){ResourceSample("exploration-"+(int)nextSample);yield return Capture("02-circuit-"+(int)nextSample);nextSample+=60;previous=Time.realtimeSinceStartupAsDouble;}}
   result.explorationSeconds=Time.realtimeSinceStartupAsDouble-start;File.WriteAllText(Path.Combine(output,"five-minute-checkpoint.json"),JsonUtility.ToJson(result,true));result.finalKnown=env.State.Discovery.Remembered.Count;Application.targetFrameRate=-1;Check(result.finalKnown>result.initialKnown+500,"Exploration learns geography without world pre-reveal");Check(result.laps>=1,"Completed integrated connected circuit");
   for(int a=0;a<2;a++){env.anchor=a;env.Go(0);yield return Settle();yield return Capture("03-remembered-distant-maze-anchor-"+a);}
   env.ResetDemo();env.Go(1);yield return Settle();Check(!StructureMesh.GroundVisible(env.State.Fixture.Landmarks[0],env.State.Discovery),"Approach leaves spike base concealed");yield return Capture("04-wide-spike-before-base");for(int a=0;a<2;a++){env.anchor=a;yield return Frames("spike-camera-"+a,120);yield return Capture("05-spike-anchor-"+a);}
   // Excavation from an actual open approach to isolated targets; bounded local waves remain physical.
   live.Teleport(Stage54Preview.V(env.State.Fixture.P(18,-18)));env.Process(.1);yield return Settle();yield return Capture("05a-spike-ground-before-collar-dig");Check(!live.World.Excavate(env.State.Fixture.X+18,env.State.Fixture.Y-27),"Protected spike base rejects excavation");for(int x=15;x<=21;x++)DirectDig("spike-collar",x,-21);yield return Settle();yield return Capture("05b-spike-collar-opened");yield return ExcavateTo(env.State.Fixture.P(-31,4),"small-pocket");yield return Frames("small-discovery",45);yield return Capture("06-small-pocket");
   yield return ExcavateTo(env.State.Fixture.P(-45,-26),"occupied-chamber");var actor=env.State.Fixture.P(-45,-26);Check(env.State.Discovery.Shown((int)actor.X,(int)actor.Y),"Rapid local threat floor visible at entry");Check(env.Lab.Actors[0].SpawnValid,"Occupied actor existed before breakthrough");env.Lab.paused=false;yield return Frames("occupied-readability",60);yield return Capture("07-occupied-local-visible");env.Lab.encounterCount=0;
   yield return ExcavateTo(env.State.Fixture.P(-77,12),"large-chamber");yield return Frames("large-chamber-reveal",60);yield return Capture("08-large-chamber");
   for(int mode=0;mode<4;mode++){env.ResetDemo();env.Go(3);env.SetReveal(mode);yield return Settle();yield return ExcavateTo(env.State.Fixture.P(94,-25),"network-entry-"+mode);env.Process(.04,false);yield return Capture("09-network-frontier-"+mode);yield return Frames("network-reveal-"+mode,90);yield return Capture("10-network-local-"+mode);Check(!env.State.Discovery.Known(env.State.Fixture.X+149,env.State.Fixture.Y-8),"Network remains bounded mode "+mode);}
   env.SetReveal(2);env.Go(2);yield return Settle();yield return Capture("11-organic-roots");foreach(int size in new[]{1,3,5,7,9}){long t=System.Diagnostics.Stopwatch.GetTimestamp();var nav=new LabNavigation(live.World,env.State.Fixture.P(54,7));bool ok=nav.TraceToRoot(env.State.Fixture.P(54,-17),size,new List<Point2>());RecordMetric("wide-root-route-"+size,StreamingGeometry.Elapsed(t),ok?1:0);Check(ok,"Wide root physical route "+size);}
   foreach(var c in new[]{new DualTile(74,-29),new DualTile(75,-29),new DualTile(76,-29)})DirectDig("root-emergence",c.X,c.Y);yield return Settle();yield return Capture("11a-root-boundary-excavated");int sb=env.StructureBuilds,pb=live.Stream.PresentationRebuilds;for(int a=0;a<2;a++){env.anchor=a;yield return Frames("camera-only-"+a,120,false);}Check(env.StructureBuilds==sb&&live.Stream.PresentationRebuilds==pb,"Camera changes do not retessellate structures or retained terrain");
   // Designated rubble opens/closes independently of memory. Dig target from free floor side; visual state preserved across refill.
   var f=env.State.Fixture;live.Teleport(Stage54Preview.V(f.P(-44,20)));yield return ExcavateTo(f.P(-38,31),"rubble-approach");live.Teleport(Stage54Preview.V(f.P(-44,20)));env.Process(.5);int remembered=env.State.Discovery.Remembered.Count;int n=env.Refill();Check(n>0,"Designated rubble can refill");Check(env.State.Discovery.Remembered.Count==remembered,"Rubble preserves geography memory");yield return Capture("12-rubble-remembered");
   for(int i=0;i<5;i++){long t=System.Diagnostics.Stopwatch.GetTimestamp();env.ResetDemo();RecordMetric("reset-"+i,StreamingGeometry.Elapsed(t));yield return Settle();ResourceSample("reset-"+i);Check(env.OwnedMeshes<=20&&live.Stream.Resident.Count<=384&&live.PooledPresentations<=8,"Reset resource bounds "+i);}
   env.debug=true;env.advanced=true;env.showPanel=true;yield return Capture("13-interface-and-palette");Finish();}
  void DirectDig(string label,int x,int y){long t=System.Diagnostics.Stopwatch.GetTimestamp();int n=live.Stream.Dig(new List<DualTile>{new DualTile(env.State.Fixture.X+x,env.State.Fixture.Y+y)});env.Process(0);RecordMetric(label,StreamingGeometry.Elapsed(t),n);RecordMetric(label+"-emergence",env.EmergenceMs,n);}
  IEnumerator ExcavateTo(Point2 target,string label)
  {
   var source=new Point2(live.Position.x,live.Position.y);var delta=target-source;int steps=(int)Math.Ceiling(LabNavigation.Distance(source,target));var cells=new List<DualTile>();
   for(int i=1;i<=steps;i++)
   {
    var p=source+delta*(i/(double)steps);long t=System.Diagnostics.Stopwatch.GetTimestamp();PreviewDigBrush.Cells(Stage54Preview.V(p),DigBrush.ThreeWide,2.2f,live.World,cells);int n=live.Stream.Dig(cells);env.Process(1.0/60);if(n>0)RecordMetric(label+"-dig",StreamingGeometry.Elapsed(t),n);
    int guard=0;while(Vector2.Distance(live.Position,Stage54Preview.V(p))>.005f&&guard++<1800){var movement=Stage54Preview.V(p)-live.Position;if(live.Ready)live.Step(Vector2.ClampMagnitude(movement/(10f/60),1),movement,false,1f/60);env.Process(1.0/60);if(label=="occupied-chamber"&&env.State.Discovery.Known(env.State.Fixture.X-45,env.State.Fixture.Y-26))Check(env.State.Discovery.Shown(env.State.Fixture.X-45,env.State.Fixture.Y-26),"Threat floor shown on remembered breakthrough");double tick=Time.realtimeSinceStartupAsDouble;yield return null;Record(label+"-excavation",(Time.realtimeSinceStartupAsDouble-tick)*1000);}Check(guard<1800,"Swept playable digging reaches waypoint "+label+" "+i);
   }
   Check(Vector2.Distance(live.Position,Stage54Preview.V(target))<.02f,"Connected dug route reaches "+label);env.Process(.15);
  }
  IEnumerator Frames(string phase,int n,bool model=true){double last=Time.realtimeSinceStartupAsDouble;for(int i=0;i<n;i++){if(model)env.Process(1.0/60);if(env.Lab.encounterCount>0&&!env.Lab.paused)env.Lab.Advance(1.0/60);yield return null;double now=Time.realtimeSinceStartupAsDouble;Record(phase,(now-last)*1000);last=now;}}
  void Record(string phase,double interval){result.frames.Add(new Frame{phase=phase,interval=interval,host=live.DisplayMs,discovery=env.DiscoveryMs,publication=live.Stream.PresentationMs,structure=env.StructureMs,emergence=env.EmergenceMs,main=main.Valid?main.LastValue*1e-6:-1,allocation=allocation.Valid?allocation.LastValue:-1,resident=live.Stream.Resident.Count,known=env.State.Discovery.Remembered.Count,shown=env.State.Discovery.Visual.Count,uploads=env.StructureUploads,built=live.Stream.TotalBuilt,evicted=live.Stream.TotalEvicted,ready=live.Ready});}
  IEnumerator Settle(){int n=0;do{env.Process(1.0/60,false);yield return null;if(++n>3000){Check(false,"Readiness timeout");yield break;}}while(!live.Ready||live.Stream.PendingPresentation>0||env.State.Discovery.PendingReleases>0);for(int i=0;i<5;i++)yield return null;}
  IEnumerator Capture(string name){yield return null;while(!live.Ready)yield return null;cam.Capture(Path.Combine(output,"captures"),name);cam.captureLabel=false;while(cam.CapturePending)yield return null;File.WriteAllText(Path.Combine(output,"captures",name+".structure.txt"),env.Inspect());double w=cam.DisplayWidth,h=w/(16.0/9);var p=live.Snapshot;result.shots.Add(new Shot{name=name,above=live.Position.y-p.Unproject(new Point2(0,-h*.5)).Y,below=p.Unproject(new Point2(0,h*.5)).Y-live.Position.y,normalScale=p.ScaleY(p.Focus.Y),anchor=env.anchor,known=env.State.Discovery.Remembered.Count,shown=env.State.Discovery.Visual.Count,resident=live.Stream.Resident.Count,visible=env.VisibleParts,x=live.Position.x,y=live.Position.y});}
  void RecordMetric(string name,double ms,int count=0)=>result.metrics.Add(new Metric{name=name,ms=ms,count=count});
  void ResourceSample(string name){GC.Collect();File.WriteAllText(Path.Combine(output,"progress.txt"),name+" / known "+env.State.Discovery.Remembered.Count+" / laps "+result.laps);result.resources.Add(new Resource{name=name,managed=GC.GetTotalMemory(true),unity=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),meshes=env.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.StartsWith("Stage54 ")),buffers=live.Gpu.BufferCount,materials=live.Gpu.ResourceCount,resident=live.Stream.Resident.Count,pool=live.PooledPresentations});}
  void Check(bool okay,string name){result.checks.Add((okay?"PASS ":"FAIL ")+name);if(!okay){result.error=name;Finish();throw new Exception(name);}}
  void Finish(){if(finished)return;finished=true;File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));allocation.Dispose();main.Dispose();Application.Quit(result.error==""?0:1);}
 }
}
